package org.apache.commons.csv;

import org.junit.Test;
import static org.junit.Assert.*;

public class CSVExceptionTest {

    @Test
    public void testConstructorWithFormatAndArgs() {
        String format = "Test message: %s";
        Object[] args = {"value"};
        CSVException exception = new CSVException(format, args);
        assertEquals("Test message: value", exception.getMessage());
    }

    @Test
    public void testConstructorWithEmptyFormat() {
        String format = "";
        Object[] args = {};
        CSVException exception = new CSVException(format, args);
        assertEquals("", exception.getMessage());
    }

    @Test
    public void testConstructorWithNullFormat() {
        String format = null;
        Object[] args = {};
        CSVException exception = new CSVException(format, args);
        assertEquals("null", exception.getMessage());
    }

    @Test
    public void testConstructorWithMultipleArgs() {
        String format = "Multiple args: %s, %d, %f";
        Object[] args = {"text", 42, 3.14};
        CSVException exception = new CSVException(format, args);
        assertEquals("Multiple args: text, 42, 3.140000", exception.getMessage());
    }

    @Test(expected = IllegalFormatException.class)
    public void testConstructorWithInvalidFormat() {
        String format = "%s";
        Object[] args = 42; // Not a valid Object array
        new CSVException(format, args);
    }
}

