package org.apache.commons.csv;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.Arrays;

import org.junit.Test;

public class CSVFormatTest {

    @Test
    public void testDefaultFormat() {
        CSVFormat format = CSVFormat.DEFAULT;
        assertEquals(",", format.getDelimiterString());
        assertEquals("\"", format.getQuoteCharacter().toString());
        assertEquals("\r\n", format.getRecordSeparator());
        assertTrue(format.getIgnoreEmptyLines());
        assertEquals(DuplicateHeaderMode.ALLOW_ALL, format.getDuplicateHeaderMode());
    }

    @Test
    public void testExcelFormat() {
        CSVFormat format = CSVFormat.EXCEL;
        assertEquals(",", format.getDelimiterString());
        assertEquals("\"", format.getQuoteCharacter().toString());
        assertEquals("\r\n", format.getRecordSeparator());
        assertFalse(format.getIgnoreEmptyLines());
        assertTrue(format.getAllowMissingColumnNames());
        assertTrue(format.getTrailingData());
        assertTrue(format.getLenientEof());
    }

    @Test
    public void testBuilder() {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setQuote('\'')
                .setRecordSeparator("\n")
                .setIgnoreEmptyLines(false)
                .setDuplicateHeaderMode(DuplicateHeaderMode.DISALLOW)
                .get();

        assertEquals(";", format.getDelimiterString());
        assertEquals("'", format.getQuoteCharacter().toString());
        assertEquals("\n", format.getRecordSeparator());
        assertFalse(format.getIgnoreEmptyLines());
        assertEquals(DuplicateHeaderMode.DISALLOW, format.getDuplicateHeaderMode());
    }

    @Test
    public void testFormatMethod() {
        CSVFormat format = CSVFormat.DEFAULT;
        String result = format.format("value1", "value2", "value3");
        assertEquals("\"value1\",\"value2\",\"value3\"", result);
    }

    @Test
    public void testNullStringHandling() {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setNullString("NULL")
                .get();

        StringWriter writer = new StringWriter();
        try (CSVPrinter printer = format.print(writer)) {
            printer.printRecord("value1", null, "value3");
        } catch (IOException e) {
            fail("IOException should not be thrown");
        }

        assertEquals("\"value1\",\"NULL\",\"value3\"\r\n", writer.toString());
    }

    @Test
    public void testHeaderHandling() {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setHeader("Name", "Email", "Phone")
                .get();

        assertArrayEquals(new String[]{"Name", "Email", "Phone"}, format.getHeader());
    }

    @Test
    public void testHeaderComments() {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setCommentMarker('#')
                .setHeaderComments("Generated by Apache Commons CSV", "2023-01-01")
                .get();

        assertEquals('#', format.getCommentMarker().charValue());
        assertArrayEquals(new String[]{"Generated by Apache Commons CSV", "2023-01-01"}, format.getHeaderComments());
    }

    @Test
    public void testCopy() {
        CSVFormat original = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setQuote('\'')
                .get();

        CSVFormat copy = original.copy();

        assertEquals(";", copy.getDelimiterString());
        assertEquals("'", copy.getQuoteCharacter().toString());
        assertNotSame(original, copy);
    }

    @Test
    public void testEqualsAndHashCode() {
        CSVFormat format1 = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setQuote('\'')
                .get();

        CSVFormat format2 = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setQuote('\'')
                .get();

        assertEquals(format1, format2);
        assertEquals(format1.hashCode(), format2.hashCode());
    }

    @Test
    public void testToString() {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setDelimiter(';')
                .setQuote('\'')
                .setNullString("NULL")
                .get();

        String expected = "Delimiter=<;> QuoteChar=<'> NullString=<NULL>";
        assertTrue(format.toString().contains(expected));
    }

    @Test
    public void testParse() throws IOException {
        String csv = "Name,Email,Phone\nJohn Doe,john@example.com,1234567890";
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setHeader("Name", "Email", "Phone")
                .get();

        try (CSVParser parser = format.parse(new StringReader(csv))) {
            CSVRecord record = parser.next();
            assertEquals("John Doe", record.get("Name"));
            assertEquals("john@example.com", record.get("Email"));
            assertEquals("1234567890", record.get("Phone"));
        }
    }

    @Test
    public void testPrint() throws IOException {
        CSVFormat format = CSVFormat.DEFAULT.builder()
                .setHeader("Name", "Email", "Phone")
                .get();

        StringWriter writer = new StringWriter();
        try (CSVPrinter printer = format.print(writer)) {
            printer.printRecord("John Doe", "john@example.com", "1234567890");
        }

        String expected = "\"Name\",\"Email\",\"Phone\"\r\n\"John Doe\",\"john@example.com\",\"1234567890\"\r\n";
        assertEquals(expected, writer.toString());
    }

    @Test
    public void testWithMethods() {
        CSVFormat original = CSVFormat.DEFAULT;
        CSVFormat modified = original.withDelimiter(';').withQuote('\'');

        assertEquals(";", modified.getDelimiterString());
        assertEquals("'", modified.getQuoteCharacter().toString());
        assertNotSame(original, modified);
    }

    @Test
    public void testDeprecatedMethods() {
        CSVFormat original = CSVFormat.DEFAULT;
        CSVFormat modified = original.withAllowMissingColumnNames(true);

        assertTrue(modified.getAllowMissingColumnNames());
        assertNotSame(original, modified);
    }
}

