package org.apache.commons.csv;

import static org.junit.Assert.*;

import java.io.IOException;
import java.io.StringReader;
import java.util.List;
import java.util.Map;

import org.junit.Test;

public class CSVParserTest {

    @Test
    public void testParseWithString() throws IOException {
        String csv = "name,age,city\nJohn,30,New York\nJane,25,Chicago";
        CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(2, records.size());
        assertEquals("John", records.get(0).get(0));
        assertEquals("30", records.get(0).get(1));
        assertEquals("New York", records.get(0).get(2));
        assertEquals("Jane", records.get(1).get(0));
        assertEquals("25", records.get(1).get(1));
        assertEquals("Chicago", records.get(1).get(2));
    }

    @Test
    public void testParseWithHeader() throws IOException {
        String csv = "name,age,city\nJohn,30,New York\nJane,25,Chicago";
        CSVFormat format = CSVFormat.DEFAULT.withHeader();
        CSVParser parser = CSVParser.parse(csv, format);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(2, records.size());
        assertEquals("John", records.get(0).get("name"));
        assertEquals("30", records.get(0).get("age"));
        assertEquals("New York", records.get(0).get("city"));
        assertEquals("Jane", records.get(1).get("name"));
        assertEquals("25", records.get(1).get("age"));
        assertEquals("Chicago", records.get(1).get("city"));
    }

    @Test
    public void testParseWithEmptyFile() throws IOException {
        String csv = "";
        CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT);
        List<CSVRecord> records = parser.getRecords();

        assertTrue(records.isEmpty());
    }

    @Test
    public void testParseWithSingleRecord() throws IOException {
        String csv = "John,30,New York";
        CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(1, records.size());
        assertEquals("John", records.get(0).get(0));
        assertEquals("30", records.get(0).get(1));
        assertEquals("New York", records.get(0).get(2));
    }

    @Test
    public void testParseWithQuotedValues() throws IOException {
        String csv = "\"John Doe\",30,\"New York, NY\"";
        CSVParser parser = CSVParser.parse(csv, CSVFormat.DEFAULT);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(1, records.size());
        assertEquals("John Doe", records.get(0).get(0));
        assertEquals("30", records.get(0).get(1));
        assertEquals("New York, NY", records.get(0).get(2));
    }

    @Test
    public void testParseWithNullValues() throws IOException {
        String csv = "name,age,city\nJohn,30,\nJane,25,Chicago";
        CSVFormat format = CSVFormat.DEFAULT.withHeader();
        CSVParser parser = CSVParser.parse(csv, format);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(2, records.size());
        assertEquals("John", records.get(0).get("name"));
        assertEquals("30", records.get(0).get("age"));
        assertNull(records.get(0).get("city"));
        assertEquals("Jane", records.get(1).get("name"));
        assertEquals("25", records.get(1).get("age"));
        assertEquals("Chicago", records.get(1).get("city"));
    }

    @Test
    public void testParseWithComments() throws IOException {
        String csv = "# This is a comment\nname,age,city\nJohn,30,New York\nJane,25,Chicago";
        CSVFormat format = CSVFormat.DEFAULT.withHeader().withCommentMarker('#');
        CSVParser parser = CSVParser.parse(csv, format);
        List<CSVRecord> records = parser.getRecords();

        assertEquals(2, records.size());
        assertEquals("John", records.get(0).get("name"));
        assertEquals("30", records.get(0).get("age"));
        assertEquals("New York", records.get(0).get("city"));
        assertEquals("Jane", records.get(1).get("name"));
        assertEquals("25", records.get(1).get("age"));
        assertEquals("Chicago", records.get(1).get("city"));
    }

